import type { GuideTopic } from "@/lib/qa-guide";

/*
 * §7.11.7: the QA guide's claims map (test-only, never shipped). Every non-empty, non-heading line of every topic, and of
 * the index, holds at least one claim's `text`; each claim names where its statement comes from: a repository file and a
 * string it contains (code or test), a spec section and a string in it, or an external page with the date it was opened.
 * web/tests/qa-guide-claims.test.ts checks every source. Change a guide line only with its claim.
 */

export type ClaimSource =
  | { kind: "code" | "test"; file: string; needle: string }
  | { kind: "spec"; section: string; needle: string }
  | { kind: "external"; url: string; checked: string }
  | { kind: "qa_read"; requestId: string; checked: string };
export type Claim = { topic: GuideTopic | "index"; text: string; source: ClaimSource };

const ETL = "etl/src/bddrug_etl";
const F = {
  clinical: `${ETL}/stages/clinical.py`,
  substances: `${ETL}/stages/substances.py`,
  ddinter: `${ETL}/stages/ddinter.py`,
  content: `${ETL}/parse/content.py`,
  names: `${ETL}/parse/names.py`,
  rxnav: `${ETL}/rxnav/client.py`,
  html: `${ETL}/ddinter/html.py`,
  queue: `${ETL}/queue.py`,
  oclClient: `${ETL}/ocl/client.py`,
  oclTransform: `${ETL}/ocl/transform.py`,
  loadDgda: `${ETL}/jobs/load_dgda.py`,
  ddinterClient: `${ETL}/ddinter/client.py`,
  loadBatches: `${ETL}/load/batches.py`,
  pipeline: `${ETL}/jobs/run_pipeline.py`,
  queueTest: "etl/tests/test_queue.py",
  clinicalTest: "etl/tests/test_stage_clinical.py",
  map: "web/lib/qa-map.ts",
  tools: "web/lib/qa-mcp-tools.ts",
  ingredients: "api/src/main/java/com/niramoy/bddrug/adapter/persistence/IngredientSummaryReader.java",
  filters: "api/src/main/java/com/niramoy/bddrug/adapter/persistence/R2dbcQaQueryAdapter.java",
  links: "api/src/main/java/com/niramoy/bddrug/domain/SourceLinks.java",
  v2: "db/migrations/V2__batches.sql",
  v3: "db/migrations/V3__pipeline.sql",
} as const;

const code = (file: string, needle: string): ClaimSource => ({ kind: "code", file, needle });
const test = (file: string, needle: string): ClaimSource => ({ kind: "test", file, needle });
const spec = (section: string, needle: string): ClaimSource => ({ kind: "spec", section, needle });
/** Opened with curl, read-only, when the guide was written. */
const external = (url: string, checked: string): ClaimSource => ({ kind: "external", url, checked });
/** The register record the guide's examples quote, read from the OCL API (fix round 1, guide 1.1.0). */
const NAPA_OCL = "https://api.tr.ocl.dghs.gov.bd/orgs/MoHFW/sources/DGDA-Drugs/concepts/186-0030-006--napa/?verbose=true&includeMappings=true";

const c = (topic: Claim["topic"], text: string, source: ClaimSource): Claim => ({ topic, text, source });

